/* =====================================================================
   IMPORTACIÓN DE LAS 500 DENUNCIAS DEL EXCEL (quemen_IHC.xlsx)
   Base de datos compartida: BD_Denuncias

   Requisitos: haber ejecutado antes los scripts 01 y 02, y haber arrancado
   una vez el primer prototipo (debe existir el usuario PNP-2045).

   Qué hace:
     1. Amplía dos columnas que quedaban cortas para los datos del Excel:
        - código de denuncia: de 12 a 20 caracteres (DEN-2026-000001 tiene 15)
        - despacho fiscal:    de 120 a 150 caracteres
     2. Registra los 70 funcionarios policiales del Excel (PNP-3001 a PNP-3070).
     3. Registra los 500 ciudadanos y sus 500 denuncias.
     4. Agrega al historial la última actualización de cada denuncia.

   No borra nada: las denuncias de demostración (D-000584...) se conservan.
   Puede ejecutarse más de una vez: lo que ya existe no se vuelve a insertar.

   Datos que el Excel NO trae y que este script completa:
     - Estado: se deduce de los días entre el registro y la última actualización
         sin actualización  -> PNP: En proceso    | Fiscalía: En investigación
         1 a 7 días         -> PNP: En proceso    | Fiscalía: Diligencias
         8 a 20 días        -> PNP: Por resolver  | Fiscalía: Con disposición
         más de 20 días     -> PNP: Resuelto      | Fiscalía: Archivado
     - Descripción de los hechos: texto armado con el tipo de denuncia y el lugar.
     - Carpeta fiscal: correlativo CF-2026-01001 a CF-2026-01500.
     - De los funcionarios: código de acceso, DNI ficticio (99000001...) y la
       misma contraseña que tiene el usuario PNP-2045.

   Cómo usarlo: abrirlo en SQL Server Management Studio y presionar F5.
   Después, REINICIA el portal ciudadano para que asigne el PIN a los nuevos ciudadanos.
   ===================================================================== */

USE BD_Denuncias;
GO
SET NOCOUNT ON;
GO

-- Comprobaciones previas: si falta algo, el script se detiene sin cambiar nada
IF COL_LENGTH('denuncia', 'id_usuario_responsable') IS NULL
BEGIN
    RAISERROR(N'Falta ejecutar antes el script 02_portal_ciudadano.sql.', 16, 1);
    SET NOEXEC ON;
END
GO
IF NOT EXISTS (SELECT 1 FROM usuario WHERE codigo = N'PNP-2045')
BEGIN
    RAISERROR(N'No existe el usuario PNP-2045: ejecuta primero el Sistema de Gestión para que cargue sus datos.', 16, 1);
    SET NOEXEC ON;
END
GO

/* ---------------------------------------------------------------------
   1. AMPLIAR COLUMNAS
   Para cambiar el tamaño de denuncia.codigo hay que quitar un momento las
   restricciones que dependen de ella y volver a crearlas después.
   --------------------------------------------------------------------- */
IF COL_LENGTH('denuncia', 'codigo') < 40   -- 40 bytes = NVARCHAR(20)
BEGIN
    -- Se quitan las claves foráneas que apuntan a denuncia.codigo y su restricción de único
    IF OBJECT_ID(N'FK_actuacion_denuncia') IS NOT NULL ALTER TABLE actuacion DROP CONSTRAINT FK_actuacion_denuncia;
    IF OBJECT_ID(N'FK_documento_denuncia') IS NOT NULL ALTER TABLE documento DROP CONSTRAINT FK_documento_denuncia;
    IF OBJECT_ID(N'FK_remision_denuncia')  IS NOT NULL ALTER TABLE remision_fiscal DROP CONSTRAINT FK_remision_denuncia;
    IF OBJECT_ID(N'UQ_denuncia_codigo')    IS NOT NULL ALTER TABLE denuncia DROP CONSTRAINT UQ_denuncia_codigo;

    -- Se amplían el código y las columnas de las otras tablas que lo guardan
    ALTER TABLE denuncia        ALTER COLUMN codigo          NVARCHAR(20) NOT NULL;
    ALTER TABLE actuacion       ALTER COLUMN codigo_denuncia NVARCHAR(20) NOT NULL;
    ALTER TABLE documento       ALTER COLUMN codigo_denuncia NVARCHAR(20) NOT NULL;
    ALTER TABLE remision_fiscal ALTER COLUMN codigo_denuncia NVARCHAR(20) NOT NULL;

    -- Se vuelven a crear las restricciones
    ALTER TABLE denuncia        ADD CONSTRAINT UQ_denuncia_codigo UNIQUE (codigo);
    ALTER TABLE actuacion       ADD CONSTRAINT FK_actuacion_denuncia FOREIGN KEY (codigo_denuncia) REFERENCES denuncia (codigo);
    ALTER TABLE documento       ADD CONSTRAINT FK_documento_denuncia FOREIGN KEY (codigo_denuncia) REFERENCES denuncia (codigo);
    ALTER TABLE remision_fiscal ADD CONSTRAINT FK_remision_denuncia  FOREIGN KEY (codigo_denuncia) REFERENCES denuncia (codigo);
END
GO
IF COL_LENGTH('denuncia', 'despacho_fiscal') < 300   -- 300 bytes = NVARCHAR(150)
    ALTER TABLE denuncia ALTER COLUMN despacho_fiscal NVARCHAR(150) NULL;
GO

/* ---------------------------------------------------------------------
   2. TABLAS TEMPORALES CON LOS DATOS DEL EXCEL
   (existen solo mientras dura esta ejecución)
   --------------------------------------------------------------------- */
DROP TABLE IF EXISTS #funcionario;
DROP TABLE IF EXISTS #excel;
-- COLLATE DATABASE_DEFAULT: las tablas temporales usan la misma regla de comparación de
-- textos que BD_Denuncias, para poder enlazarlas con las tablas reales sin conflictos
CREATE TABLE #funcionario (
    codigo    NVARCHAR(20) COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY,  -- código de acceso generado (PNP-3001...)
    rango     NVARCHAR(60) COLLATE DATABASE_DEFAULT NOT NULL,              -- grado, tomado del Excel
    nombres   NVARCHAR(80) COLLATE DATABASE_DEFAULT NOT NULL,
    apellidos NVARCHAR(80) COLLATE DATABASE_DEFAULT NOT NULL,
    dni       NVARCHAR(8) COLLATE DATABASE_DEFAULT  NOT NULL               -- DNI ficticio: el Excel no lo trae
);
CREATE TABLE #excel (
    codigo             NVARCHAR(20) COLLATE DATABASE_DEFAULT  NOT NULL PRIMARY KEY,
    tipo_delito        NVARCHAR(60) COLLATE DATABASE_DEFAULT  NOT NULL,
    despacho_fiscal    NVARCHAR(150) COLLATE DATABASE_DEFAULT NOT NULL,
    fiscal_responsable NVARCHAR(120) COLLATE DATABASE_DEFAULT NOT NULL,
    codigo_funcionario NVARCHAR(20) COLLATE DATABASE_DEFAULT  NOT NULL,
    nombres            NVARCHAR(80) COLLATE DATABASE_DEFAULT  NOT NULL,
    apellidos          NVARCHAR(80) COLLATE DATABASE_DEFAULT  NOT NULL,
    dni                NVARCHAR(8) COLLATE DATABASE_DEFAULT   NOT NULL,
    correo             NVARCHAR(120) COLLATE DATABASE_DEFAULT NOT NULL,
    telefono           NVARCHAR(15) COLLATE DATABASE_DEFAULT  NOT NULL,
    fecha_registro     DATETIME2     NOT NULL,
    ultima_actualizacion DATETIME2   NOT NULL,
    lugar_hechos       NVARCHAR(200) COLLATE DATABASE_DEFAULT NOT NULL,
    estado_policial    NVARCHAR(30) COLLATE DATABASE_DEFAULT  NOT NULL,     -- deducido (ver encabezado)
    estado_fiscal      NVARCHAR(30) COLLATE DATABASE_DEFAULT  NOT NULL,     -- deducido (ver encabezado)
    carpeta_fiscal     NVARCHAR(20) COLLATE DATABASE_DEFAULT  NOT NULL      -- correlativo generado
);
GO

-- Funcionarios del Excel (70)
GO

-- Denuncias del Excel (500), en bloques de 100 filas
GO

GO

GO

GO

GO

/* ---------------------------------------------------------------------
   3. PASAR LOS DATOS A LAS TABLAS DEL SISTEMA
   Todo va en una transacción: si algo falla, no se guarda nada a medias.
   --------------------------------------------------------------------- */
SET XACT_ABORT ON;
BEGIN TRANSACTION;

-- 3.1 Funcionarios policiales. Reciben la misma contraseña (ya cifrada) del usuario PNP-2045.
SELECT f.codigo, (SELECT password_hash FROM usuario WHERE codigo = N'PNP-2045'),
       f.nombres, f.apellidos, f.dni, N'PNP', N'POLICIA', f.rango, N'Policía Nacional del Perú', 1
FROM #funcionario f
WHERE NOT EXISTS (SELECT 1 FROM usuario u WHERE u.codigo = f.codigo);

-- 3.2 Módulos habilitados para esos funcionarios (los seis del sistema)
SELECT u.id_usuario, m.modulo
FROM usuario u
JOIN #funcionario f ON f.codigo = u.codigo
CROSS JOIN (VALUES (N'denuncias'), (N'tracking'), (N'documents'), (N'reports'), (N'chat'), (N'schedule')) AS m(modulo)
WHERE NOT EXISTS (SELECT 1 FROM usuario_permiso p WHERE p.id_usuario = u.id_usuario AND p.modulo = m.modulo);

-- 3.3 Ciudadanos (el PIN lo asigna el portal ciudadano al arrancar)
SELECT e.nombres, e.apellidos, e.dni, e.correo, e.telefono
FROM #excel e
WHERE NOT EXISTS (SELECT 1 FROM ciudadano c WHERE c.dni = e.dni);

-- 3.4 Denuncias, enlazadas con su ciudadano (por DNI) y su funcionario responsable (por código)
                      estado_policial, estado_fiscal, carpeta_fiscal, despacho_fiscal, fiscal_responsable, id_usuario_responsable)
SELECT e.codigo, c.id_ciudadano, e.tipo_delito,
       N'Denuncia por ' + LOWER(e.tipo_delito) + N' presentada por ' + e.nombres + N' ' + e.apellidos
           + N'. Los hechos ocurrieron en ' + e.lugar_hechos + N'.',
       e.lugar_hechos, e.fecha_registro, e.ultima_actualizacion,
       e.estado_policial, e.estado_fiscal, e.carpeta_fiscal, e.despacho_fiscal, e.fiscal_responsable, u.id_usuario
FROM #excel e
JOIN ciudadano c ON c.dni = e.dni
JOIN usuario u ON u.codigo = e.codigo_funcionario
WHERE NOT EXISTS (SELECT 1 FROM denuncia d WHERE d.codigo = e.codigo);

-- 3.5 Historial: la última actualización de cada denuncia (las que nunca se actualizaron no llevan registro)
SELECT d.id_denuncia, e.codigo_funcionario, N'POLICIA', e.estado_policial, NULL, e.ultima_actualizacion
FROM #excel e
JOIN denuncia d ON d.codigo = e.codigo
WHERE e.ultima_actualizacion > e.fecha_registro
  AND NOT EXISTS (SELECT 1 FROM seguimiento_denuncia s WHERE s.id_denuncia = d.id_denuncia);

COMMIT TRANSACTION;
GO

/* ---------------------------------------------------------------------
   4. RESUMEN
   --------------------------------------------------------------------- */
SELECT (SELECT COUNT(*) FROM denuncia WHERE codigo LIKE N'DEN-2026-%')  AS denuncias_del_excel,
       (SELECT COUNT(*) FROM denuncia)                                 AS denuncias_en_total,
       (SELECT COUNT(*) FROM ciudadano)                                AS ciudadanos_en_total,
       (SELECT COUNT(*) FROM usuario WHERE codigo LIKE N'PNP-3%')      AS funcionarios_del_excel;
GO

DROP TABLE IF EXISTS #funcionario;
DROP TABLE IF EXISTS #excel;
SET NOEXEC OFF;
GO
